-- Add herb name links to all 15 existing class notes synopses.
-- Herb names that have no matching herb record (Asian Ginseng, Orange Peel) stay as plain bold.
-- Self-references (e.g. Astragalus within the Astragalus synopsis) are not linked.

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Agarita</strong> is an <strong>antimicrobial</strong> herb related to <a href="?herb=33"><strong>Oregon Grape</strong></a>, indicated for <strong>wound wash</strong> preparations; its <strong>berberine</strong> content provides broad-spectrum <strong>antimicrobial</strong> action.$$ WHERE common_name = 'Agarita';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Agrimony</strong> is an <strong>astringent</strong> herb for <strong>urinary</strong> and <strong>reproductive</strong> health; it is also used as a <strong>flower essence</strong> in the Rescue Remedy context for <strong>children's anxiety</strong>, <strong>panic</strong>, and <strong>overwhelm</strong>.$$ WHERE common_name = 'Agrimony';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Alfalfa</strong> (Medicago sativa) is a highly <strong>nutritive</strong>, <strong>mineralizing</strong>, <strong>diuretic</strong>, <strong>lymphatic</strong>, <strong>alterative</strong>, <strong>cardioprotective</strong>, <strong>anti-inflammatory</strong>, <strong>bone-building</strong>, and <strong>hypolipidemic</strong> legume-family herb that tastes salty; its roots penetrate 30 feet into the soil making it "chock full of minerals," and it contains <strong>phytosterols</strong>, <strong>inositol</strong>, B vitamins (B1, B2, B3, B5, B6, B9, B12), and <strong>chlorophyll</strong>. It is alkalizing to the <strong>gut</strong>, balances fluids, restores <strong>electrolytes</strong>, and nourishes the <strong>kidney</strong> and <strong>bladder</strong>; best extracted in water or vinegar over long periods (optimum steep 1-4 hours), and must be dried a rich green to be of good quality. It is a blood-building herb for cold constitution (with <a href="?herb=1009"><strong>Dong Quai</strong></a>, <a href="?herb=20"><strong>Ashwagandha</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=2238"><strong>White Peony</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>) and indicated for a dry constitution (with <a href="?herb=43"><strong>Nettles</strong></a>, <a href="?herb=155"><strong>Red Raspberry</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>). The thyroid picture: moderate <strong>malabsorption</strong>, poor appetite, nervousness, weakness, poor nutritional status - <strong>nourishing</strong> for <strong>hormone regulation</strong>, <strong>cardioprotective</strong>, <strong>bone-building</strong>, and <strong>hypolipidemic</strong>. It supports <strong>calcium</strong> and <strong>potassium</strong> levels, builds <strong>bones</strong>, strengthens <strong>hair</strong> and <strong>teeth</strong>, supports <strong>hormonal regulation</strong> and <strong>estrogen</strong> pathways (as a legume), buffers blood in liver excess, and is indicated for <strong>anemia in pregnancy</strong>. It appears in the stress-depletion mineral formula (<a href="?herb=155"><strong>Raspberry Leaf</strong></a>, <a href="?herb=178"><strong>Oat Straw</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>), the inositol-rich tea blend for <strong>PMOS</strong>/fertility (<a href="?herb=225"><strong>Astragalus</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=1547"><strong>Kudzu</strong></a>), Fertili-Tea (<a href="?herb=225"><strong>Astragalus</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>), Legume Tea for Fertility, Iron Tonic Syrup for pregnancy (3 tablespoons), a nourishing post-menopausal tea (<a href="?herb=43"><strong>Nettles</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>), nourishing infusions with <a href="?herb=42"><strong>Red Clover</strong></a> for <strong>thyroid</strong>/<strong>Hashimoto's</strong> support, a herbal salt recipe, and a nutritive oxymel (<a href="?herb=43"><strong>Nettles</strong></a>, <a href="?herb=122"><strong>Dandelion</strong></a>, <strong>Seaweed</strong>, <a href="?herb=178"><strong>Oat Straw</strong></a>); also in a topical spray for pet <strong>hot spots</strong> (<a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=22"><strong>Burdock</strong></a>, <a href="?herb=122"><strong>Dandelion</strong></a>, <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=81"><strong>St. John's Wort</strong></a>). Suggested as part of a morning routine as an <strong>alterative</strong>.$$ WHERE common_name = 'Alfalfa';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Aloe</strong> is a <strong>moistening</strong>, <strong>cooling</strong>, <strong>bitter</strong>, and <strong>astringent</strong> herb that is <strong>anticarcinogenic</strong>, <strong>immunomodulating</strong>, and <strong>alkaline-rich</strong>, making it useful in <strong>cancer</strong> care - paired with chlorophyll as a gentle, initial approach to <strong>inflammation</strong> reduction in <strong>cancer</strong> support. It is best indicated for the <strong>bladder</strong> - <strong>UTI</strong> and <strong>cystitis</strong> - and supportive for the <strong>gut lining</strong>, especially for <strong>heartburn</strong>, taken as aloe juice with electrolytes and a little lime. Topically, fresh gel is cooling and healing on <strong>burns</strong>, <strong>wounds</strong>, and <strong>rash</strong>; <strong>Aloe</strong> is <strong>demulcent</strong>, <strong>emollient</strong>, and <strong>anti-inflammatory</strong> for <strong>burns</strong>, where <a href="?herb=2748"><strong>Prickly Pear cactus</strong></a> can substitute; salves shine for <strong>abrasions</strong>. <strong>NEVER use Aloe on a staph infection - it can seal in the bacteria.</strong> <strong>NO for wound wash on deep wounds - Aloe heals too fast; also avoid introducing oils into open tissue (no salves on open wounds).</strong> As a carrier for vaginal washes, note that oils can change the pH of <strong>mucous tissues</strong> - a wash or sitz bath is the better delivery method.$$ WHERE common_name = 'Aloe';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>American Ginseng</strong> (Panax quinquefolius) is a warming, moistening <strong>adaptogen</strong> that creates a non-specific state of resistance to environmental, psychological, and physiological stress by regulating the <strong>H-P-A axis</strong>. It is a key herb for <strong>blood sugar dysregulation</strong>, improving <strong>insulin sensitivity</strong>, lowering <strong>cortisol</strong>, and supporting <strong>hyperlipidemia</strong>; it is also <strong>cardioprotective</strong>. Energetically it is more neutral and mild than <a href="?herb=14"><strong>Asian Ginseng</strong></a> - possibly less stimulating than <a href="?herb=14"><strong>Panax</strong></a> - and is indicated where there is low metabolic fire. Onset of effect: 7-10 days. Dose: Tincture 1:5, 2-4 ml TID. Note: expensive and overharvested.$$ WHERE common_name = 'American Ginseng';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Andrographis</strong> is the "king of bitters" - MOST bitter - and an <strong>anti-inflammatory</strong>, <strong>antioxidant</strong>, <strong>adaptogen</strong>, <strong>hypoglycemic</strong>, <strong>cardioprotective</strong>, <strong>antiviral</strong>, and <strong>immunostimulant</strong> herb. It is specific for <strong>liver congestion</strong> with <strong>fat intolerance</strong> and <strong>sluggish liver</strong>; indicated in <strong>arthritis</strong>, <strong>type 2 diabetes</strong>, <strong>tick bites</strong> (antimicrobial/antiviral support, paired with <a href="?herb=225"><strong>Astragalus</strong></a>), and <strong>influenza</strong>; recommended for active infection (unlike <a href="?herb=225"><strong>Astragalus</strong></a>). Take with a tissue moistener like <a href="?herb=45"><strong>marshmallow</strong></a> glycerite. Dose: tincture 1 ml 3x/day. <strong>NOT for use in pregnancy or when trying to conceive.</strong>$$ WHERE common_name = 'Andrographis';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Angelica</strong> (Archangelica) is a MEDIUM <strong>bitter</strong>, warming herb - clearing to the sinuses during tasting - that acts as a <strong>mild nervine</strong> and is <strong>hormone balancing</strong>. It is a <strong>functional digestive stimulant</strong> for <strong>upper GI deficiency</strong> and <strong>hypochlorhydria</strong>, stimulating digestive secretions including <strong>HCL</strong>, <strong>pancreatic juices</strong>, and <strong>bile</strong>; found in the EP all-purpose bitter formula and used in digestive oxymels. Respiratorily, it addresses <strong>spasmodic cough</strong> by breaking the feedback loop where coughing triggers more <strong>bronchial spasm</strong>; it also functions as a <strong>relaxing expectorant</strong> and <strong>bronchodilator</strong>, appears in the antispasmodic formula for <strong>asthma</strong>, and is in the Deep Lung Formula for <strong>bronchitis</strong> (with <a href="?herb=54"><strong>Elecampane</strong></a>, <a href="?herb=590"><strong>Yerba Santa</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=73"><strong>Hawthorn</strong></a>, <a href="?herb=61"><strong>Mullein</strong></a>, <a href="?herb=309"><strong>Yerba Mansa</strong></a>, <a href="?herb=21"><strong>Garlic</strong></a>, <a href="?herb=104"><strong>Osha</strong></a>).$$ WHERE common_name = 'Angelica';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Arnica</strong> flowers oil is indicated for <strong>strains</strong>, <strong>sprains</strong>, and <strong>bruises</strong>, though high quality flowers are hard to find; it is also used in salve with <a href="?herb=1597"><strong>Frankincense</strong></a> for topical <strong>joint inflammation</strong> treatment.$$ WHERE common_name = 'Arnica';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Artichoke leaf</strong> is a MEDIUM <strong>bitter</strong> - described as very green and verdant - that is cooling and drying; it is a <strong>cooling bitter</strong> for <strong>hypochlorhydria</strong> and also a <strong>hepatic</strong> for hot constitution, pairing with <a href="?herb=61"><strong>Mullein</strong></a> for <strong>liver</strong> and hydration. It is "mostly <strong>choleretic</strong>" - increasing <strong>bile production</strong> by the liver, helpful especially in the <strong>lower intestinal tract</strong> - and is <strong>amphoteric</strong> in regulating <strong>peristalsis</strong> in the <strong>small intestine</strong> with no unintended side effects elsewhere (slows down or speeds up as needed). It stimulates digestion, wakes up the <strong>stomach</strong>, supports <strong>high cholesterol</strong> and <strong>blood pressure</strong>, inhibits <strong>H. pylori</strong> (<strong>peptic ulcer</strong>), and is effective for <strong>nausea</strong> and <strong>bloating</strong> before meals. Found in many herbal bitters blends and the EP all-purpose bitter formula; recommended as bitters before mealtime alongside <a href="?herb=122"><strong>Dandelion</strong></a> root or leaf; used for digestive support in <strong>perimenopause</strong> (with <a href="?herb=983"><strong>Blue Vervain</strong></a>, <strong>Orange Peel</strong>, <a href="?herb=102"><strong>Gentian</strong></a>) and for rekindling digestive fire. Also nice as a glycerite.$$ WHERE common_name = 'Artichoke';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Asafetida</strong> is an aromatic <strong>pungent</strong> spice with <strong>strong sedative</strong>, <strong>antiviral</strong>, <strong>nervine</strong>, and <strong>anti-inflammatory</strong> properties; it is listed among Black Herbal <strong>cardiovascular</strong> herbs and described as "warding off viral load." It is <strong>anticarcinogenic</strong> - inhibiting, mitigating, preventing, and potentially helping to cure <strong>cancer</strong> - and is used as a <strong>nervine</strong> to calm and reduce pain in early-stage <strong>cancer</strong> care as well as for <strong>digestion</strong> in cancer support. Historical use in the American South for <strong>asthma</strong> and <strong>colic</strong>, administered as a tincture or worn raw around the neck (contemporary period, post-slavery). Listed alongside <a href="?herb=178"><strong>Oat Straw</strong></a>/<a href="?herb=178"><strong>Oat Tops</strong></a> as a <strong>nervine</strong> for <strong>cardiovascular</strong> support.$$ WHERE common_name = 'Asafetida';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Ashwagandha</strong> is a warming, moistening <strong>adaptogen</strong> - a nightshade - that regulates the <strong>H-P-A axis</strong>, resists stress, and works best over 3-6 months at moderate to higher doses. It is a <strong>yang tonic</strong> in Ayurveda for masculine energy; it stimulates <strong>metabolism</strong>, increases <strong>vitality</strong>, <strong>endurance</strong>, and <strong>physical exercise tolerance</strong>; it increases <strong>sperm motility</strong>, reduces <strong>stress hormones</strong>, and raises <strong>testosterone</strong> by reducing cortisol conversion; it is a <strong>nervine/adaptogen</strong> for <strong>ADHD</strong> and <strong>anxiety</strong> (underlying chronic stress); and it is an <strong>antifibrotic</strong> (with <a href="?herb=2238"><strong>White Peony</strong></a> and <a href="?herb=225"><strong>Astragalus</strong></a>), an <strong>immune amphoteric</strong> (deep nourisher), and a key herb in <strong>cancer</strong> care. It is an <strong>immunomodulator</strong> given once the patient begins to feel better (recovery phase, not acute stage). It is a modulating <strong>adaptogen</strong> for <strong>thyroid</strong>-related <strong>depression</strong>, specifically indicated for the <strong>hypothyroid</strong> picture - foggy, forgetful, slow transit time - and used in adaptogen/nervine tinctures for <strong>thyroid</strong>/<strong>Hashimoto's</strong> cases (with <a href="?herb=178"><strong>Milky Oats</strong></a> and <a href="?herb=78"><strong>Licorice</strong></a>) and in the main absorption tincture (<a href="?herb=13"><strong>Tulsi</strong></a>, <a href="?herb=17"><strong>Schisandra</strong></a>, <a href="?herb=206"><strong>Milk Thistle</strong></a>, <a href="?herb=109"><strong>Rosemary</strong></a>). For <strong>cognitive decline</strong> associated with <strong>hypertension</strong>: indicated for <strong>nervous exhaustion</strong>, <strong>anemia</strong>, depleted and frazzled, forgetful because frazzled. Also indicated for <strong>emotional depletion</strong> and <strong>burnout</strong>; for <strong>blood sugar dysregulation</strong> (constitutional support tincture); as an adaptogen for wet constitution (but <strong>not if hot/wet</strong>); and as a blood-building herb for cold constitution (with <a href="?herb=1009"><strong>Dong Quai</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=2238"><strong>White Peony</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>). Best administered as a fluid extract in milk: dose 1/2 tsp powder or 15-30 drops; for sleep at night, simmer 1/2 tsp with <a href="?herb=167"><strong>Cinnamon</strong></a> and <a href="?herb=127"><strong>Cardamom</strong></a> in milk of choice, add <a href="?herb=1595"><strong>Nutmeg</strong></a> (Lisa's sleep formula). Described as a "cozy bathrobe" - grounding but not directly sleep-inducing - used with <a href="?herb=137"><strong>Passionflower</strong></a> for sleep and anxiety. Also used with <a href="?herb=45"><strong>Marshmallow Root</strong></a> and <a href="?herb=167"><strong>Cinnamon</strong></a> for <strong>gut inflammation</strong>. <strong>Can cause irritability and aggravation in some people; if this occurs, switch to a different adaptogen.</strong>$$ WHERE common_name = 'Ashwagandha';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Astragalus</strong> (Astragalus membranaceus) is a sweet, warming, and deeply moistening <strong>adaptogen</strong> - an <strong>immune amphoteric</strong>, <strong>cardiac tonic</strong>, <strong>diuretic</strong>, <strong>nephroprotective</strong>, <strong>hepatoprotective</strong>, <strong>antifibrotic</strong>, <strong>antioxidant</strong>, <strong>circulation-enhancing</strong>, <strong>anti-inflammatory</strong>, and <strong>restorative tonic</strong>. Its polysaccharides modulate immunity, improve <strong>insulin sensitivity</strong>, and inhibit <strong>insulin resistance</strong>; it contains <strong>isoflavones</strong> and <strong>saponin triterpenes</strong> for hormone modulation and induces apoptosis (eliminating aging and dead cells). It is the primary <strong>pulmonary trophorestorative</strong> and the most-used herb in <strong>asthma</strong>; a tonic to <strong>lungs</strong> and <strong>kidneys</strong>, deeply restorative and building after prolonged high stress. In TCM, used for "wasting and thirsting syndrome" (3 Ps: polyuria, polyphagia, polydipsia) in conjunction with <a href="?herb=1009"><strong>Angelica sinensis</strong></a> (5:1 ratio). It is hypotensive, vasodilating, and cardiodepressive - too much can cause excess fluid in the tissues and a pounding heartbeat. Indicated for post-menopausal dryness (moistening adaptogen), <strong>poor circulation</strong>, <strong>slow digestion</strong>, <strong>constipation</strong>, <strong>low immunity</strong>, stagnation, <strong>anxiety</strong>, <strong>eczema</strong>, <strong>psoriasis</strong>, <strong>diarrhea</strong> (with <a href="?herb=11"><strong>Reishi</strong></a>), <strong>lymph/immune deficiency</strong>, and <strong>common cold</strong>/<strong>influenza</strong> (immune tonic - use after the acute phase resolves). It is a liver alterative for hot constitution, a nourishing foundation when <a href="?herb=14"><strong>ginseng</strong></a> would be premature, and an adaptogen for prebiotic support (limit complexity in therapy). Dose: decoction 2 tsp:12 oz water or tincture 1-3 ml 3x/day (or 2-4 ml TID); needs 4-hour decoction (Instant Pot) to be effective. Acute dosing: frequent at high therapeutic range. Chronic/tonic dosing: medium-low and consistent. In fertility: protects from oxidative stress, supports <strong>sperm motility</strong> and semen quality; found in Fertili-Tea and Legume Tea for Fertility (with <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>); inositol-rich tea blend for <strong>PMOS</strong> (with <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=1547"><strong>Kudzu</strong></a>). In liver tea (2P <a href="?herb=22"><strong>Burdock</strong></a>, 2P <strong>Astragalus</strong>, 1P <a href="?herb=122"><strong>Dandelion</strong></a>, 1P <strong>Orange Peel</strong>, 1P <a href="?herb=76"><strong>Fennel</strong></a>, 1P <a href="?herb=78"><strong>Licorice</strong></a>); immune decoction (28g <a href="?herb=57"><strong>Elderberries</strong></a>, 28g <strong>Astragalus</strong>, 14g <a href="?herb=124"><strong>Ginger</strong></a> to 32 oz water); oxymel (1 oz <strong>Astragalus</strong>, 3 oz <a href="?herb=43"><strong>Nettle</strong></a>); herbal broth (2 sticks); adaptogen/immune tonic protocol with <a href="?herb=11"><strong>Reishi</strong></a> and <a href="?herb=17"><strong>Schisandra</strong></a>. <strong>Safety: do NOT take during active infection - so potent in moistening it can drive the infection deeper into the tissues and push the body to dampness. Aggravates damp conditions and fungal infections (polysaccharides feed yeast). Use Andrographis for active infection instead. Only resume Astragalus for prevention and tonic use once out of infection.</strong>$$ WHERE common_name = 'Astragalus';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Bacopa</strong> is a <strong>nootropic</strong> herb with deep Ayurvedic roots that supports <strong>memory</strong>, <strong>cognitive function</strong>, <strong>focus</strong>, and <strong>brain health</strong>; it calms <strong>neuroinflammation</strong>, reduces <strong>anxiety</strong>, nourishes the <strong>nervous system</strong> and <strong>heart</strong>, and reduces inflammation generally. It is indicated for <strong>ADHD</strong>, <strong>brain fog</strong>, <strong>thyroid-related depression</strong> and <strong>hypothyroid</strong>-induced mood and memory impairment, <strong>PCOS</strong> (in the "Temple of Devotion" formula for focus and anxiety), <strong>blood sugar dysregulation</strong> (constitutional support), and <strong>stress</strong> and <strong>sleep</strong> support. Traditional Ayurvedic use includes head massage oil with <strong>Bacopa</strong> and <a href="?herb=165"><strong>Ginkgo</strong></a>. Useful addition to complex tonics addressing <strong>cognitive decline</strong>.$$ WHERE common_name = 'Bacopa';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Barberry</strong> is a berberine-containing plant that increases <strong>insulin sensitivity</strong>, reduces <strong>triglycerides</strong>, and lowers <strong>leptin</strong>; it is a key herb for <strong>blood sugar dysregulation</strong> and <strong>perimenopause</strong> blood sugar support (alongside <a href="?herb=33"><strong>Oregon Grape Root</strong></a>). It is <strong>antimicrobial</strong> in wound wash and <strong>antifungal</strong>. As a "strong <strong>cholagogue</strong>" it promotes <strong>bile flow</strong>/release from the <strong>gallbladder</strong> and enhances digestive secretions (Thompson's Standard Protocol; upper GI deficiency). <strong>Caution: strong cholagogues can trigger pain or attacks if gallstones or obstruction risk is present.</strong>$$ WHERE common_name = 'Barberry';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Basil</strong> is a warming spice for <strong>Cold and Dry</strong> constitutions and a smaller source of <strong>Vitamin A</strong>/Beta carotene. It and <a href="?herb=84"><strong>Chamomile</strong></a> can sweeten dreams when nightmares are present (in the context of <a href="?herb=115"><strong>Mugwort</strong></a> dreamwork use). <strong>Basil hydrosol</strong> is a <strong>skin tonic</strong> and <strong>insect repellent</strong>. <strong>Safety: Basil has a higher concentration of Estragole - linked to liver cancer and blood clotting.</strong>$$ WHERE common_name = 'Basil';
